using Astronomy.MediaFactory.Core.KnowledgeFoundation;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeStatementKindFilterTests{[Fact]public void Constructs_and_normalizes(){var caller=new List<KnowledgeStatementKind>{KnowledgeStatementKind.Visual,KnowledgeStatementKind.Scientific,KnowledgeStatementKind.Scientific};var f=new AstronomyKnowledgeStatementKindFilter(caller);caller.Add(KnowledgeStatementKind.Visual);Assert.Equal(AstronomyKnowledgeQueryMatchMode.Any,f.MatchMode);Assert.Equal(new[]{KnowledgeStatementKind.Scientific,KnowledgeStatementKind.Visual},f.Values);Assert.Throws<NotSupportedException>(()=>((IList<KnowledgeStatementKind>)f.Values).Add(KnowledgeStatementKind.Scientific));}[Fact]public void Supports_all_mode(){var f=new AstronomyKnowledgeStatementKindFilter([KnowledgeStatementKind.Scientific],AstronomyKnowledgeQueryMatchMode.All);Assert.Equal(AstronomyKnowledgeQueryMatchMode.All,f.MatchMode);}[Fact]public void Rejects_invalid_inputs(){Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeStatementKindFilter([]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeStatementKindFilter([(KnowledgeStatementKind)99]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeStatementKindFilter([KnowledgeStatementKind.Scientific],(AstronomyKnowledgeQueryMatchMode)99));}}
